#!/bin/bash
set -euo pipefail

# ---------------------------------------------------------------
# EC2 user_data — installs Docker, pulls ECR images, starts services
# Generated by Terraform — do not edit manually
#
# Template variables (from ec2.tf templatefile):
#   ${region}             — AWS region
#   ${account_id}         — AWS account ID (dynamic via data.aws_caller_identity)
#   ${cloud_node_repo}    — ECR repo URL for cloud-node
#   ${scheduler_repo}     — ECR repo URL for scheduler
#   ${orchestrator_repo}  — ECR repo URL for orchestrator
#   ${db_secret_arn}      — Secrets Manager ARN for DB credentials
#   ${db_host}            — RDS endpoint hostname
#   ${db_port}            — RDS port
#   ${db_name}            — database name
#   ${docker_compose_b64} — base64-encoded docker-compose.yml
# ---------------------------------------------------------------

exec > >(tee /var/log/edgecloud-init.log) 2>&1
echo "=== EdgeCloud init started at $(date -u) ==="

# --- System updates + Docker ---
echo "[1/7] Installing Docker and system packages..."
dnf update -y
dnf install -y docker aws-cli jq
systemctl enable docker
systemctl start docker
usermod -aG docker ec2-user

# --- Swap file (1GB safety net for t3.small 2GB RAM) ---
echo "[2/7] Creating 1GB swap..."
fallocate -l 1G /swapfile
chmod 600 /swapfile
mkswap /swapfile
swapon /swapfile
echo '/swapfile none swap sw 0 0' >> /etc/fstab

# --- Docker Compose (standalone binary) ---
echo "[3/7] Installing Docker Compose..."
curl -L "https://github.com/docker/compose/releases/latest/download/docker-compose-linux-x86_64" \
  -o /usr/local/bin/docker-compose
chmod +x /usr/local/bin/docker-compose
echo "Docker Compose $(docker-compose version --short)"

# --- Authenticate Docker to ECR ---
AWS_REGION="${region}"
AWS_ACCOUNT_ID="${account_id}"
echo "[4/7] Authenticating to ECR..."
# NOTE: bash vars in this file MUST use $VAR without braces - templatefile()
# interpolates any brace form and would treat it as a template variable.
aws ecr get-login-password --region "$AWS_REGION" | \
  docker login --username AWS --password-stdin "$AWS_ACCOUNT_ID.dkr.ecr.$AWS_REGION.amazonaws.com"

# --- Pull images from ECR ---
echo "[5/7] Pulling ECR images..."
docker pull "${cloud_node_repo}:latest"
docker tag "${cloud_node_repo}:latest" edgecloud-cloud:latest
docker pull "${scheduler_repo}:latest"
docker tag "${scheduler_repo}:latest" edgecloud-scheduler:latest
docker pull "${orchestrator_repo}:latest"
docker tag "${orchestrator_repo}:latest" edgecloud-orchestrator:latest
echo "Images pulled:"
docker images --format '  {{.Repository}}:{{.Tag}} {{.Size}}' | grep edgecloud

# --- Fetch DB credentials from Secrets Manager ---
echo "[6/7] Configuring services..."
DB_PASSWORD=$(aws secretsmanager get-secret-value \
  --secret-id "${db_secret_arn}" \
  --region "$AWS_REGION" \
  --query SecretString --output text | jq -r '.password')

# --- Prepare deployment directory ---
mkdir -p /opt/edgecloud

# --- Create .env (awk avoids sed special-char issues with passwords) ---
DB_HOST="${db_host}"
DB_PORT="${db_port}"
DB_NAME="${db_name}"

awk -v db_host="$DB_HOST" -v db_port="$DB_PORT" -v db_name="$DB_NAME" -v db_pass="$DB_PASSWORD" \
  '{
    gsub(/__DB_HOST__/, db_host);
    gsub(/__DB_PORT__/, db_port);
    gsub(/__DB_NAME__/, db_name);
    gsub(/__DB_PASSWORD__/, db_pass);
    print
  }' > /opt/edgecloud/.env <<'ENVEOF'
# Edge-Cloud Orchestration — AWS Environment
CLOUD_PORT=8001
SCHEDULER_PORT=8002
ORCHESTRATOR_PORT=8003
ORCHESTRATOR_PORT_EXT=8003
DATABASE_HOST=__DB_HOST__
DATABASE_PORT=__DB_PORT__
DATABASE_NAME=__DB_NAME__
DATABASE_USER=edgecloud_admin
DATABASE_PASSWORD=__DB_PASSWORD__
DATABASE_URL=postgresql://edgecloud_admin:__DB_PASSWORD__@__DB_HOST__:__DB_PORT__/__DB_NAME__
ENVEOF

# --- Write docker-compose.yml (base64-encoded in user_data) ---
echo "${docker_compose_b64}" | base64 -d > /opt/edgecloud/docker-compose.yml

# --- Start services ---
echo "[7/7] Starting services..."
cd /opt/edgecloud
docker-compose up -d

# --- Health check with timeout ---
echo "Waiting for services to become healthy..."
HEALTH_OK=false
for i in $(seq 1 30); do
  sleep 10
  CLOUD_OK=$(curl -sf http://localhost:8001/health 2>/dev/null | jq -r '.status' 2>/dev/null || echo "down")
  SCHED_OK=$(curl -sf http://localhost:8002/health 2>/dev/null | jq -r '.status' 2>/dev/null || echo "down")
  ORCH_OK=$(curl -sf http://localhost:80/health 2>/dev/null | jq -r '.status' 2>/dev/null || echo "down")
  echo "  [$((i * 10))s] cloud=$CLOUD_OK scheduler=$SCHED_OK orchestrator=$ORCH_OK"
  if [ "$CLOUD_OK" = "ok" ] && [ "$SCHED_OK" = "ok" ] && [ "$ORCH_OK" = "ok" ]; then
    HEALTH_OK=true
    break
  fi
done

if [ "$HEALTH_OK" = "true" ]; then
  echo "=== EdgeCloud init completed successfully at $(date -u) ==="
else
  echo "=== EdgeCloud init completed with warnings at $(date -u) ==="
  echo "Some services may still be starting. Check: docker ps"
fi
